 */
import React from "react";

export function Buttons2() {
  return (
    <div dangerouslySetInnerHTML={{ __html: "
    <style>
        .gradient-border-1 {
            background: linear-gradient(var(--gradient-angle, 0deg), #FF0080, #7928CA, #FF0080);
            animation: gradient-rotate 3s linear infinite;
        }

        .gradient-border-2 {
            background: linear-gradient(var(--gradient-angle, 0deg), #00FF87, #60EFFF, #00FF87);
            animation: gradient-rotate 3s linear infinite;
        }

        .gradient-border-3 {
            background: linear-gradient(var(--gradient-angle, 0deg), #FF8A00, #FF0080, #FF8A00);
            animation: gradient-rotate 3s linear infinite;
        }

        .gradient-border-4 {
            background: linear-gradient(var(--gradient-angle, 0deg), #3B82F6, #14B8A6, #3B82F6);
            animation: gradient-rotate 3s linear infinite;
        }

        @property --gradient-angle {
            syntax: "<angle>";
            initial-value: 0deg;
            inherits: false;
        }

        @keyframes gradient-rotate {
            0% {
                --gradient-angle: 0deg;
            }
            100% {
                --gradient-angle: 360deg;
            }
        }

        .button-wrapper {
            transition: transform 0.3s cubic-bezier(0.34, 1.56, 0.64, 1);
        }

        .button-wrapper:hover {
            transform: scale(1.05) translateY(-5px);
        }

        .gradient-border-hover {
            transition: all 0.3s cubic-bezier(0.34, 1.56, 0.64, 1);
        }

        .button-wrapper:hover .gradient-border-hover {
            opacity: 1;
            filter: blur(8px);
        }

        .button-content {
            transition: transform 0.3s cubic-bezier(0.34, 1.56, 0.64, 1);
            will-change: transform;
        }

        .button-wrapper:hover .button-content {
            transform: translateY(-2px);
        }

        .icon-rotate {
            transition: transform 0.5s cubic-bezier(0.34, 1.56, 0.64, 1);
        }

        .button-wrapper:hover .icon-rotate {
            transform: rotate(-10deg) scale(1.2);
        }
    </style>
</head>
<body class="bg-white min-h-screen flex items-center justify-center p-4">
    <div class="flex flex-col sm:flex-row gap-6 items-center">
        <!-- Original Pink/Purple Button -->
        <div class="button-wrapper">
            <div class="relative group">
                <div class="absolute -inset-1 rounded-lg gradient-border-1 gradient-border-hover blur opacity-75"></div>
                <button class="relative px-8 py-4 bg-white rounded-lg">
                    <div class="button-content relative flex items-center gap-2">
                        <svg class="w-5 h-5 text-neutral-800 icon-rotate" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                            <path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M13 10V3L4 14h7v7l9-11h-7z"></path>
                        </svg>
                        <span class="text-neutral-800 font-bold text-lg">
                            Power Up
                        </span>
                    </div>
                </button>
            </div>
        </div>

        <!-- Green/Cyan Button -->
        <div class="button-wrapper">
            <div class="relative group">
                <div class="absolute -inset-1 rounded-lg gradient-border-2 gradient-border-hover blur opacity-75"></div>
                <button class="relative px-8 py-4 bg-white rounded-lg">
                    <div class="button-content relative flex items-center gap-2">
                        <svg class="w-5 h-5 text-neutral-800 icon-rotate" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                            <path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M12 8v4m0 4h.01M21 12a9 9 0 11-18 0 9 9 0 0118 0z"></path>
                        </svg>
                        <span class="text-neutral-800 font-bold text-lg">
                            Activate
                        </span>
                    </div>
                </button>
            </div>
        </div>

        <!-- Orange/Pink Button -->
        <div class="button-wrapper">
            <div class="relative group">
                <div class="absolute -inset-1 rounded-lg gradient-border-3 gradient-border-hover blur opacity-75"></div>
                <button class="relative px-8 py-4 bg-white rounded-lg">
                    <div class="button-content relative flex items-center gap-2">
                        <svg class="w-5 h-5 text-neutral-800 icon-rotate" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                            <path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M17.657 18.657A8 8 0 016.343 7.343S7 9 9 10c0-2 .5-5 2.986-7C14 5 16.09 5.777 17.656 7.343A7.975 7.975 0 0120 13a7.975 7.975 0 01-2.343 5.657z"></path>
                        </svg>
                        <span class="text-neutral-800 font-bold text-lg">
                            Ignite
                        </span>
                    </div>
                </button>
            </div>
        </div>

        <!-- Blue/Teal Button -->
        <div class="button-wrapper">
            <div class="relative group">
                <div class="absolute -inset-1 rounded-lg gradient-border-4 gradient-border-hover blur opacity-75"></div>
                <button class="relative px-8 py-4 bg-white rounded-lg">
                    <div class="button-content relative flex items-center gap-2">
                        <svg class="w-5 h-5 text-neutral-800 icon-rotate" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                            <path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M13 10V3L4 14h7v7l9-11h-7z"></path>
                        </svg>
                        <span class="text-neutral-800 font-bold text-lg">
                            Launch
                        </span>
                    </div>
                </button>
            </div>
        </div>
    </div>
</body>
</html>" }} />
  );
}
